GMHelper.materialBagId = nil
function GMHelper:DownloadBlockTextures()
    local url = "http://static.sandboxol.cn/games/material/undefined.package_09_64.1678417150816.zip"
    local path = FileUtil:getTexturePackPath() .. "21.zip"
    local fun = function(data, code)
        print("data ======>", json.encode(data))
        print("code ======>", code)
    end
    WebService:DownloadFile(url, path, fun)
end

function GMHelper:GetBlockTextures()
    local fun = function(data, code)
        local log = "code:" .. code
        if code == 1 then
            if data then
                log = log .. " data:" .. json.encode(data)
                GMHelper.materialBagId = tostring(data.materialBagId)
            end
        end
        CustomDialog.builder()
            .setTitleText("获取当前材质包")
            .setContentText(log)
            .setRightText("确定")
            .show()
        GUIGMControlPanel:hide()
    end
    WebService:GetUsingMaterialBag(fun)
end

function GMHelper:ChangeBlockTextures()
    GMHelper:openInput({ "zip文件名" }, function(materialBagId)
        if GMHelper.materialBagId then
            materialBagId = GMHelper.materialBagId
        end
        CustomDialog.builder()
            .setTitleText("设置材质包")
            .setContentText(materialBagId)
            .setRightText("确定")
            .show()
        if not materialBagId then
            return
        end
        local path = FileUtil:getTexturePackPath()
        local fun = function(_, code)
            if code == 1 then
                Blockman.Instance():changeBlockTextures(path)
                GUIGMControlPanel:hide()
            end
        end
        if #materialBagId == 0 then
            path = ""
            WebService:CancelUseMaterialBag(fun)
        else
            path = FileUtil:getTexturePackPath() .. materialBagId .. ".zip"
            WebService:UseMaterialBag(materialBagId, fun)
        end
    end)
end

