function GMHelper:checkLuaMemoryBegin()
    local mri = require "engine_base.debug.MemoryReferenceInfo"
    mri.m_cConfig.m_bAllMemoryRefFileAddTime = false
    local name = "mem_check_begin"
    collectgarbage("collect")
    local basePath = Root.Instance():getWriteablePath() .. "/"
    mri.m_cMethods.DumpMemorySnapshot(basePath, name, -1)
end

function GMHelper:checkLuaMemoryEnd()

    local mri = require "engine_base.debug.MemoryReferenceInfo"
    mri.m_cConfig.m_bAllMemoryRefFileAddTime = false
    local name = "mem_check_end"
    --collectgarbage("collect")
    local basePath = Root.Instance():getWriteablePath() .. "/"
    mri.m_cMethods.DumpMemorySnapshot(basePath, name, -1)
    mri.m_cMethods.DumpMemorySnapshotComparedFile(basePath, "Compared", -1,
            string.format(basePath .. "LuaMemRefInfo-All-[%s].txt", "mem_check_begin"),
            string.format(basePath .. "LuaMemRefInfo-All-[%s].txt", "mem_check_end"))

end

